/* @lc app=leetcode id=3924 lang=kotlin */ class Solution { fun ok(n: Int, edges: Array<IntArray>, s: Int, t: Int, k: Int, th: Int): Boolean = edges.flatMap { (a, b, w) -> listOf(a to (b to w), b to (a to w)) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { Int.MAX_VALUE }.also { it[s] = 0 }.let { d -> java.util.ArrayDeque<Int>().also { it.add(s) }.let { dq -> generateSequence { dq.pollFirst() }.forEach { u -> g[u].orEmpty().forEach { (v, w) -> (d[u] + (if (w > th) 1 else 0)).let { nd -> if (nd < d[v]) d.set(v, nd).also { if (w > th) dq.addLast(v) else dq.addFirst(v) } } } }.let { d[t] <= k } } } } fun minimumThreshold(n: Int, edges: Array<IntArray>, source: Int, target: Int, k: Int): Int = if (!ok(n, edges, source, target, k, 1_000_000_000)) -1 else generateSequence(0 to 1_000_000_000) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (ok(n, edges, source, target, k, m)) lo to m else m + 1 to hi } }.last().first }